//! 🧱️ Declares required chunk custody before an append-only container header is published.
use super::*;
fn enter(depth:u16,container:bool,options:&EncodeOptions,checkpoint:&mut impl FnMut()->Result<(),ValueError>)->Result<(),ValueError>{checkpoint()?;if container&&depth>options.limits.max_depth{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"Pack chunk declaration exceeds authored depth"));}Ok(())}
pub(super) fn intrinsic(value:&DslValue,options:&EncodeOptions,depth:u16,checkpoint:&mut impl FnMut()->Result<(),ValueError>)->Result<bool,ValueError>{enter(depth,matches!(value,DslValue::Array(_)|DslValue::Object(_)),options,checkpoint)?;Ok(match value{DslValue::Bytes(bytes)=>!bytes.is_empty()&&bytes.len()as u64>=options.chunk_threshold,DslValue::Array(values)=>{let mut found=false;for value in values{found|=intrinsic(value,options,depth+1,checkpoint)?;}found},DslValue::Object(values)=>{let mut found=false;for(_,value)in values{found|=intrinsic(value,options,depth+1,checkpoint)?;}found},_=>false})}
pub(super) fn field(value:&FieldValue,options:&EncodeOptions,depth:u16,checkpoint:&mut impl FnMut()->Result<(),ValueError>)->Result<bool,ValueError>{enter(depth,matches!(value,FieldValue::List(_)|FieldValue::Tuple(_)|FieldValue::Map(_)|FieldValue::Statements(_)|FieldValue::Block(_)),options,checkpoint)?;Ok(match value{FieldValue::Bytes64(bytes)=>!bytes.is_empty()&&bytes.len()as u64>=options.chunk_threshold,FieldValue::List(values)|FieldValue::Tuple(values)=>{let mut found=false;for value in values{found|=field(value,options,depth+1,checkpoint)?;}found},FieldValue::Map(values)=>{let mut found=false;for(_,value)in values{found|=field(value,options,depth+1,checkpoint)?;}found},FieldValue::Record(value)=>record(value,options,depth,checkpoint)?,FieldValue::Statements(values)=>{let mut found=false;for(_,value)in values{found|=record(value,options,depth+1,checkpoint)?;}found},FieldValue::Block(value)=>field(value,options,depth+1,checkpoint)?,FieldValue::Value(value)=>intrinsic(value,options,depth+1,checkpoint)?,FieldValue::Wire(value)=>intrinsic(&value.properties,options,depth+1,checkpoint)?,_=>false})}
pub(super) fn record(value:&RecordValue,options:&EncodeOptions,depth:u16,checkpoint:&mut impl FnMut()->Result<(),ValueError>)->Result<bool,ValueError>{enter(depth,true,options,checkpoint)?;let mut found=false;for value in value.fields.values(){found|=field(value,options,depth+1,checkpoint)?;}Ok(found)}
